import java.util.*;
import java.math.*;

public class Main {
    static final long MAX_VAL = 1234567890L;
    static final int thousandth = 47;
    static final double epsilon = 1e-8;
    static final int pattern_size = 9;
    static final double PI = 3.14159265358979323846;

    public static <T extends Number> T get_abs(T x) {
        if (x.doubleValue() < 0) {
            return (T) Double.valueOf(-x.doubleValue());
        } else {
            return x;
        }
    }

    static long mod_pow(long base, long exp, long modulus) {
        if (exp <= 0) return 1;
        long half_pow = mod_pow(base, exp / 2, modulus);
        half_pow = (half_pow * half_pow) % modulus;
        return (exp & 1) == 1 ? (half_pow * base) % modulus : half_pow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total_N = sc.nextInt();
        int total_M = sc.nextInt();
        long modulus = sc.nextLong();

        long[] fact = new long[total_N + 1];
        long[] inv_fact = new long[total_N + 1];

        fact[0] = 1;
        inv_fact[0] = 1;
        for (int i = 1; i <= total_N; i++) {
            fact[i] = (fact[i - 1] * i) % modulus;
            inv_fact[i] = (inv_fact[i - 1] * mod_pow(i, modulus - 2, modulus)) % modulus;
        }

        long[] count_arr = new long[total_M + 1];
        long[] sum_arr = new long[total_M + 1];

        Arrays.fill(count_arr, 0);
        Arrays.fill(sum_arr, 0);
        count_arr[0] = 1;

        for (int m = 1; m <= total_M; m++) {
            for (int k = 0; k < m; k++) {
                long left_c = (count_arr[k] * inv_fact[k]) % modulus;
                long right_c = (count_arr[m - 1 - k] * inv_fact[m - 1 - k]) % modulus;
                long left_s = (sum_arr[k] * inv_fact[k]) % modulus;
                long right_s = (sum_arr[m - 1 - k] * inv_fact[m - 1 - k]) % modulus;

                count_arr[m] = (count_arr[m] + left_c * right_c % modulus * (m + 1)) % modulus;

                long temp_sum = (left_s * right_s + left_c * right_s + left_s * right_c) % modulus;
                sum_arr[m] = (sum_arr[m] + temp_sum * (m + 1)) % modulus;

                long numerator = k * (k + 1) + (m - k) * (m - k - 1);
                long denominator = 2;
                long term = (left_c * right_c) % modulus * numerator % modulus * mod_pow(denominator, modulus - 2, modulus) % modulus;
                sum_arr[m] = (sum_arr[m] + term) % modulus;
            }
            count_arr[m] = (count_arr[m] * fact[m - 1]) % modulus;
            sum_arr[m] = (sum_arr[m] * fact[m - 1]) % modulus;
        }

        long[][] count_result = new long[total_N + 1][total_M + 1];
        long[][] sum_result = new long[total_N + 1][total_M + 1];

        for (int i = 0; i <= total_N; i++) {
            Arrays.fill(count_result[i], 0);
            Arrays.fill(sum_result[i], 0);
        }

        count_result[0][0] = 1;

        for (int i = 1; i <= total_N; i++) {
            for (int j = 0; j <= Math.min(i, total_M); j++) {
                count_result[i][j] = count_result[i - 1][j];
                sum_result[i][j] = sum_result[i - 1][j];

                if (j == i) {
                    count_result[i][j] = (count_result[i][j] + count_arr[i] * inv_fact[i]) % modulus;
                    sum_result[i][j] = (sum_result[i][j] + sum_arr[i] * inv_fact[i]) % modulus;
                }

                for (int k = 1; k <= Math.min(j, i - 1); k++) {
                    long c = (count_arr[k] * inv_fact[k]) % modulus;
                    long s = (sum_arr[k] * inv_fact[k]) % modulus;

                    long temp_c = (count_result[i - 1 - k][j - k] * c) % modulus;
                    count_result[i][j] = (count_result[i][j] + temp_c) % modulus;

                    long temp_s = (sum_result[i - 1 - k][j - k] * c + count_result[i - 1 - k][j - k] * s) % modulus;
                    sum_result[i][j] = (sum_result[i][j] + temp_s) % modulus;
                }
            }
        }

        long final_answer = (sum_result[total_N][total_M] * fact[total_M]) % modulus;
        System.out.println(final_answer);
        sc.close();
    }
